import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"開発者ガイド","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/dev-guide/index.md","filePath":"ja-JP/dev-guide/index.md","lastUpdated":1785993908000}'),s={name:"ja-JP/dev-guide/index.md"};function i(l,e,n,d,c,g){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="開発者ガイド" tabindex="-1">開発者ガイド <a class="header-anchor" href="#開発者ガイド" aria-label="Permalink to &quot;開発者ガイド&quot;">​</a></h1><p>Lertaro は、サードパーティ製アセンブリが検索動作の拡張、コンテキストメニューアクションの追加、他のウィンドウとの統合、UI のカスタマイズを行うためにターゲットできる、オープンなプラグイン SDK (<code>Lertaro.PluginSdk</code>)を提供しています。本ガイドではこの SDK の全体を解説します。</p><ul><li><strong><a href="./architecture.html">アーキテクチャ</a></strong> — App、バックグラウンドの Service、プラグインがどのように組み合わさっているか。</li><li><strong><a href="./getting-started.html">はじめに</a></strong> — プラグインプロジェクトの雛形作成と読み込み。</li><li><strong>プラグイン SDK リファレンス</strong>: <ul><li><strong><a href="./sdk/core-search-actions.html">コア検索とアクション</a></strong> — 検索結果と結果アクションの提供。</li><li><strong><a href="./sdk/system-adapters.html">システム / ダイアログアダプター</a></strong> — File Explorer、ネイティブファイルダイアログ、その他のフォアグラウンドウィンドウとの統合。</li><li><strong><a href="./sdk/ui-extensions.html">UI とプレビューの拡張</a></strong> — サイドバーフィルター、結果列、ファイルプレビュー、サムネイル、テーマ、翻訳。</li><li><strong><a href="./sdk/abstractions.html">共有抽象化</a></strong> — プラグインが受け取る読み取り専用モデル(<code>ISearchResult</code>、 <code>IPluginSearchWindow</code>)と設定スキーマ(<code>IConfigurable</code>)。</li><li><strong><a href="./sdk/services.html">ホストサービス</a></strong> — ホストがプラグインに公開する静的サービス(アイコン、お気に入り、履歴、ファイルメタデータ、ディレクトリインデックス作成、プラグインごとの設定、ログ)。</li></ul></li><li><strong><a href="./examples.html">サンプルプラグイン</a></strong> — 実際に同梱されている2つのプラグインのケーススタディ。</li><li><strong><a href="./packaging.html">パッケージングと配布</a></strong> — ビルドされたプラグイン DLL がどのように発見され、読み込まれるか。</li></ul><p>ここに記載されているすべてのインターフェースシグネチャは、現在の <code>PluginSdk</code> ソースと直接照合して検証済みです——もし食い違いを見つけた場合は、コードの方が正となります。</p>',4)])])}const m=t(s,[["render",i]]);export{p as __pageData,m as default};
